CREATE TRIGGER course_sync_cursor_assessment_tag_gradebook AFTER INSERT OR DELETE OR UPDATE ON public.assessment_tag FOR EACH ROW EXECUTE FUNCTION public._touch_course_sync_cursor_from_trigger('gradebook', 'assessment');
CREATE TRIGGER course_sync_cursor_score_gradebook AFTER INSERT OR DELETE OR UPDATE ON public.score FOR EACH ROW EXECUTE FUNCTION public._touch_course_sync_cursor_from_trigger('gradebook', 'enrollment');
CREATE TRIGGER course_sync_cursor_tag_score_gradebook AFTER INSERT OR DELETE OR UPDATE ON public.tag_score FOR EACH ROW EXECUTE FUNCTION public._touch_course_sync_cursor_from_trigger('gradebook', 'enrollment');
CREATE TRIGGER course_sync_cursor_rubric_score_gradebook AFTER INSERT OR DELETE OR UPDATE ON public.rubric_score FOR EACH ROW EXECUTE FUNCTION public._touch_course_sync_cursor_from_trigger('gradebook', 'enrollment');
CREATE TRIGGER course_sync_cursor_rubric_check_score_gradebook AFTER INSERT OR DELETE OR UPDATE ON public.rubric_check_score FOR EACH ROW EXECUTE FUNCTION public._touch_course_sync_cursor_from_trigger('gradebook', 'assessment');
CREATE TRIGGER course_sync_cursor_course_gradebook AFTER INSERT OR DELETE OR UPDATE ON public.course FOR EACH ROW EXECUTE FUNCTION public._touch_course_sync_cursor_from_trigger('gradebook', 'course');
CREATE TRIGGER course_sync_cursor_student_gradebook AFTER UPDATE ON public.student FOR EACH ROW EXECUTE FUNCTION public._touch_course_sync_cursor_from_trigger('gradebook', 'student');
CREATE TRIGGER course_sync_cursor_enrollment_gradebook AFTER INSERT OR DELETE OR UPDATE ON public.enrollment FOR EACH ROW EXECUTE FUNCTION public._touch_course_sync_cursor_from_trigger('gradebook', 'course');

alter table public.course_sync_cursor enable row level security;
create policy course_sync_cursor_via_course on public.course_sync_cursor for select to public using (public.fv_owns_course(course_id));
alter table public.subject enable row level security;
create policy subject_via_course on public.subject for all to public using (public.fv_owns_course(course_id)) with check (public.fv_owns_course(course_id));
alter table public.competency_group enable row level security;
create policy competency_group_via_course on public.competency_group for all to public using (public.fv_owns_course(course_id)) with check (public.fv_owns_course(course_id));
alter table public.section enable row level security;
create policy section_via_course on public.section for all to public using (public.fv_owns_course(course_id)) with check (public.fv_owns_course(course_id));
alter table public.tag enable row level security;
create policy tag_via_section on public.tag for all to public using ((EXISTS ( SELECT 1
   FROM public.section s
  WHERE ((s.id = tag.section_id) AND public.fv_owns_course(s.course_id))))) with check ((EXISTS ( SELECT 1
   FROM public.section s
  WHERE ((s.id = tag.section_id) AND public.fv_owns_course(s.course_id)))));
alter table public.category enable row level security;
create policy category_via_course on public.category for all to public using (public.fv_owns_course(course_id)) with check (public.fv_owns_course(course_id));
alter table public.module enable row level security;
create policy module_via_course on public.module for all to public using (public.fv_owns_course(course_id)) with check (public.fv_owns_course(course_id));
alter table public.rubric enable row level security;
create policy rubric_via_course on public.rubric for all to public using (public.fv_owns_course(course_id)) with check (public.fv_owns_course(course_id));
alter table public.criterion enable row level security;
create policy criterion_via_rubric on public.criterion for all to public using ((EXISTS ( SELECT 1
   FROM public.rubric r
  WHERE ((r.id = criterion.rubric_id) AND public.fv_owns_course(r.course_id))))) with check ((EXISTS ( SELECT 1
   FROM public.rubric r
  WHERE ((r.id = criterion.rubric_id) AND public.fv_owns_course(r.course_id)))));
alter table public.criterion_check enable row level security;
create policy criterion_check_via_parents on public.criterion_check for all to public using ((EXISTS ( SELECT 1
   FROM (public.criterion cr
     JOIN public.rubric r ON ((r.id = cr.rubric_id)))
  WHERE ((cr.id = criterion_check.criterion_id) AND public.fv_owns_course(r.course_id))))) with check ((EXISTS ( SELECT 1
   FROM (public.criterion cr
     JOIN public.rubric r ON ((r.id = cr.rubric_id)))
  WHERE ((cr.id = criterion_check.criterion_id) AND public.fv_owns_course(r.course_id)))));
alter table public.criterion_tag enable row level security;
create policy criterion_tag_via_parents on public.criterion_tag for all to public using ((EXISTS ( SELECT 1
   FROM (public.criterion cr
     JOIN public.rubric r ON ((r.id = cr.rubric_id)))
  WHERE ((cr.id = criterion_tag.criterion_id) AND public.fv_owns_course(r.course_id))))) with check ((EXISTS ( SELECT 1
   FROM (public.criterion cr
     JOIN public.rubric r ON ((r.id = cr.rubric_id)))
  WHERE ((cr.id = criterion_tag.criterion_id) AND public.fv_owns_course(r.course_id)))));
alter table public.rubric_tag enable row level security;
create policy rubric_tag_via_parents on public.rubric_tag for all to public using ((EXISTS ( SELECT 1
   FROM public.rubric r
  WHERE ((r.id = rubric_tag.rubric_id) AND public.fv_owns_course(r.course_id))))) with check ((EXISTS ( SELECT 1
   FROM ((public.rubric r
     JOIN public.tag t ON ((t.id = rubric_tag.tag_id)))
     JOIN public.section s ON ((s.id = t.section_id)))
  WHERE ((r.id = rubric_tag.rubric_id) AND (s.course_id = r.course_id) AND public.fv_owns_course(r.course_id)))));
alter table public.assessment enable row level security;
create policy assessment_via_course on public.assessment for all to public using (public.fv_owns_course(course_id)) with check (public.fv_owns_course(course_id));
alter table public.assessment_tag enable row level security;
create policy assessment_tag_via_assessment on public.assessment_tag for all to public using (public.fv_owns_assessment(assessment_id)) with check (public.fv_owns_assessment(assessment_id));
alter table public.score enable row level security;
create policy score_via_enrollment on public.score for all to public using (public.fv_owns_enrollment(enrollment_id)) with check (public.fv_owns_enrollment(enrollment_id));
alter table public.score_audit enable row level security;
create policy score_audit_read on public.score_audit for select to public using ((EXISTS ( SELECT 1
   FROM public.score s
  WHERE ((s.id = score_audit.score_id) AND public.fv_owns_enrollment(s.enrollment_id)))));
alter table public.tag_score enable row level security;
create policy tag_score_via_enrollment on public.tag_score for all to public using (public.fv_owns_enrollment(enrollment_id)) with check (public.fv_owns_enrollment(enrollment_id));
alter table public.rubric_score enable row level security;
create policy rubric_score_via_enrollment on public.rubric_score for all to public using (public.fv_owns_enrollment(enrollment_id)) with check (public.fv_owns_enrollment(enrollment_id));
alter table public.rubric_check_score enable row level security;
create policy rubric_check_score_via_enrollment on public.rubric_check_score for all to public using (public.fv_owns_enrollment(enrollment_id)) with check (public.fv_owns_enrollment(enrollment_id));
